cJSON * cJSON_CreateTopLevel(const struct TopLevel * x) {
    cJSON * j = NULL;
    if (NULL != x) {
        if (NULL != (j = cJSON_CreateObject())) {
            if (NULL != x->base_path) {
                cJSON_AddStringToObject(j, "basePath", x->base_path);
            }
            else {
                cJSON_AddStringToObject(j, "basePath", "");
            }
            cJSON_AddItemToObject(j, "definitions", cJSON_CreateDefinitions(x->definitions));
            if (NULL != x->host) {
                cJSON_AddStringToObject(j, "host", x->host);
            }
            else {
                cJSON_AddStringToObject(j, "host", "");
            }
            cJSON_AddItemToObject(j, "info", cJSON_CreateInfo(x->info));
            cJSON_AddItemToObject(j, "paths", cJSON_CreatePaths(x->paths));
            if (NULL != x->produces) {
                cJSON * j1 = cJSON_AddArrayToObject(j, "produces");
                if (NULL != j1) {
                    char * x1 = list_get_head(x->produces);
                    while (NULL != x1) {
                        cJSON_AddItemToArray(j1, cJSON_CreateString(x1));
                        x1 = list_get_next(x->produces);
                    }
                }
            }
            if (NULL != x->schemes) {
                cJSON * j1 = cJSON_AddArrayToObject(j, "schemes");
                if (NULL != j1) {
                    char * x1 = list_get_head(x->schemes);
                    while (NULL != x1) {
                        cJSON_AddItemToArray(j1, cJSON_CreateString(x1));
                        x1 = list_get_next(x->schemes);
                    }
                }
            }
            if (NULL != x->swagger) {
                cJSON_AddStringToObject(j, "swagger", x->swagger);
            }
            else {
                cJSON_AddStringToObject(j, "swagger", "");
            }
        }
    }
    return j;
}

